"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["31281"],{71732(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.idade_maxima_emissao.campos_incompletos","status":422,"titulo":"Valor, Unidade e ReferenciaTipo devem estar todos presentes, ou todos ausentes"},"descricao":{"codigo":"uniplus.selecao.idade_maxima_emissao.campos_incompletos","requisitos":["UNI-REQ-0066"],"oQueAconteceu":["A idade m\xe1xima de emiss\xe3o do documento exigido chegou com s\xf3 parte dos campos: valor, unidade e\\ntipo precisam estar todos presentes, ou todos ausentes. A regra pela metade n\xe3o diz nem quanto\\ntempo vale, nem a partir de quando.","A idade m\xe1xima de emiss\xe3o \xe9 uma regra opcional de cada documento exigido: limita h\xe1 quanto tempo o\\ncomprovante enviado pode ter sido emitido (por exemplo, no m\xe1ximo 90 dias), contado a partir de um\\nmarco de refer\xeancia. Ela \xe9 dada por um valor, uma unidade (`DIAS`, `MESES` ou `ANOS`) e o tipo de\\nrefer\xeancia: `FIM_INSCRICAO`, `INICIO_FASE`, `FIM_FASE`, `DATA_ESPECIFICA` ou `DATA_SUBMISSAO`. Ela funciona como\\naviso e n\xe3o bloqueia a presen\xe7a do documento. A regra \xe9 tudo ou nada: ou os tr\xeas campos est\xe3o\\nausentes (sem regra), ou os tr\xeas est\xe3o presentes, com a data quando o tipo \xe9 `DATA_ESPECIFICA` e a fase\\nquando \xe9 `INICIO_FASE` ou `FIM_FASE`.","A confer\xeancia \xe9 feita na montagem de cada exig\xeancia, e \xe9 a primeira das tr\xeas restri\xe7\xf5es do arquivo\\n(idade m\xe1xima de emiss\xe3o, formatos permitidos e modelo citado). Dentro da idade m\xe1xima, as causas\\ns\xe3o conferidas nesta ordem: [`campos_incoerentes_com_ausencia`](/erros/uniplus.selecao.idade_maxima_emissao.campos_incoerentes_com_ausencia), [`campos_incompletos`](/erros/uniplus.selecao.idade_maxima_emissao.campos_incompletos),\\n[`valor_invalido`](/erros/uniplus.selecao.idade_maxima_emissao.valor_invalido), [`data_incoerente_com_tipo`](/erros/uniplus.selecao.idade_maxima_emissao.data_incoerente_com_tipo) e [`fase_incoerente_com_tipo`](/erros/uniplus.selecao.idade_maxima_emissao.fase_incoerente_com_tipo); a primeira que falha interrompe a\\nmontagem.","O valor menor ou igual a zero, a unidade e o tipo desconhecidos n\xe3o chegam a esta confer\xeancia:\\ns\xe3o recusados antes, na valida\xe7\xe3o do pedido."],"comoResolver":["Preencha os tr\xeas campos para ter a regra, ou deixe os tr\xeas vazios para n\xe3o ter limite de idade\\nde emiss\xe3o, e envie a defini\xe7\xe3o dos documentos exigidos de novo."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Idade maxima emissao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);